import { supabase } from '../lib/supabase';

/**
 * Upload an image to Supabase Storage
 * @param {File} file - The image file to upload
 * @param {string} userId - The user ID for folder organization
 * @param {string} bucket - The storage bucket name (default: 'post-images')
 * @returns {Promise<string>} - The public URL of the uploaded image
 */
export async function uploadImage(file, userId, bucket = 'post-images') {
  if (!file) return null;

  // Validate file type
  if (!file.type.startsWith('image/') && !file.type.startsWith('video/')) {
    throw new Error('File must be an image or video');
  }

  // Validate file size (max 50MB for videos, 10MB for images)
  const maxSize = file.type.startsWith('video/') ? 50 * 1024 * 1024 : 10 * 1024 * 1024;
  if (file.size > maxSize) {
    throw new Error(`File must be less than ${maxSize / (1024 * 1024)}MB`);
  }

  // ✅ Generate unique filename with timestamp and random string
  const fileExt = file.name.split('.').pop();
  const timestamp = Date.now();
  const randomString = Math.random().toString(36).substring(2, 10);
  const fileName = `${userId}/${timestamp}-${randomString}.${fileExt}`;
  const {
    error
  } = await supabase.storage.from(bucket).upload(fileName, file, {
    cacheControl: '3600',
    upsert: false,
    // ✅ Never overwrite existing files
    contentType: file.type
  });
  if (error) {
    console.error('Upload error:', error);
    throw new Error('Failed to upload file: ' + error.message);
  }
  const {
    data
  } = supabase.storage.from(bucket).getPublicUrl(fileName);
  return data.publicUrl;
}

/**
 * Delete an image from Supabase Storage
 * @param {string} filePath - The full file path in storage
 * @param {string} bucket - The storage bucket name (default: 'post-images')
 */
